    using System;

class GfG {
    public static int[][] applyDiff2D(int[][] mat, int[][] opr) {
        int n = mat.Length;
        int m = mat[0].Length;

        // diff matrix of size n x m 
        int[][] diff = new int[n][];
        for (int i = 0; i < n; i++) diff[i] = new int[m];

        // apply all operations using 4-point updates
        foreach (var q in opr) {
            int v = q[0];
            int r1 = q[1], c1 = q[2], r2 = q[3], c2 = q[4];

            // top-left -> add
            diff[r1][c1] += v;

            // top-right -> subtract
            if (c2 + 1 < m) diff[r1][c2 + 1] -= v;

            // bottom-left -> subtract
            if (r2 + 1 < n) diff[r2 + 1][c1] -= v;

            // bottom-right -> add
            if (r2 + 1 < n && c2 + 1 < m) diff[r2 + 1][c2 + 1] += v;
        }

        // row-wise prefix sum
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                diff[i][j] += diff[i][j - 1];
            }
        }

        // column-wise prefix sum
        for (int j = 0; j < m; j++) {
            for (int i = 1; i < n; i++) {
                diff[i][j] += diff[i - 1][j];
            }
        }

        // apply diff to original matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                mat[i][j] += diff[i][j];
            }
        }

        return mat;
    }

    static void Main() {
        int[][] mat = new int[][] {
            new int[] {1, 2, 3},
            new int[] {1, 1, 0},
            new int[] {4, -2, 2}
        };

        int[][] opr = new int[][] {
            new int[] {2, 0, 0, 1, 1},
            new int[] {-1, 1, 0, 2, 2}
        };

        int[][] res = applyDiff2D(mat, opr);

        foreach (var row in res) {
            foreach (var val in row)
                Console.Write(val + " ");
            Console.WriteLine();
        }
    }
}


